import{_ as r,l as i,o as e,c as s,v as t,p as n,x as l,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"分配器攻击","description":"","frontmatter":{"title":"分配器攻击","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heap-allocator-attacks.md","filePath":"cs/heap-allocator-attacks.md","lastUpdated":1789023840000}'),p={name:"cs/heap-allocator-attacks.md"};function E(u,a,A,_,m,B){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="分配器攻击" tabindex="-1">分配器攻击 <a class="header-anchor" href="#分配器攻击" aria-label="Permalink to &quot;分配器攻击&quot;">​</a></h1><div class="epigraph"><p>分配器在块头里记账：大小、空闲链表。用户数据溢出进块头，等于让 malloc 按敌手的账本工作。加固分配器把元数据与用户数据隔开、把链表指针加密，仍不是内存安全。</p><footer>—— 据 Doug Lea 的分配器叙述；Szekeres SoK；对照 ptmalloc/jemalloc 的加固演进</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/heap-uaf">UAF</a>已经能串对象。缺口是<strong>分配器元数据</strong>作为额外攻击面。本课讲为何溢出/双重释放会破坏堆契约，以及隔离与校验指针一类防御——不给改链表的操作序列。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典 chunk 把 size 与 fd/bk 放在用户数据旁边。溢出改 fd 则空闲链表被劫持——只陈述性质。双重释放让同一块进两次表。缺口是：分配器是 TCB，要校验与隔离。</p><h3 id="不是「选用某-libc-就结束」" tabindex="-1">不是「选用某 libc 就结束」 <a class="header-anchor" href="#不是「选用某-libc-就结束」" aria-label="Permalink to &quot;不是「选用某 libc 就结束」&quot;">​</a></h3><p>加固提高代价。任意写仍可能。安全语言减少到达分配器的路径。</p><p><span class="marginnote">dlmalloc 叙事是历史对照。今日分配器有 cookie、随机、隔离。本课禁止利用笔记。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：内联元数据 vs 隔离页。列出防御：canary 式 chunk 校验、unlink 检查、隔离释放。指向 sanitizer 与 fuzzer 后课。</p>',12)),(e(),n(h,null,{default:l(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20OVF%5B%22%E6%BA%A2%E5%87%BA%E8%BF%9B%E5%9D%97%E5%A4%B4%22%5D%0A%20%20OVF%20--%3E%20META%5B%22%E7%A9%BA%E9%97%B2%E9%93%BE%E8%A1%A8%E8%A2%AB%E7%A0%B4%E5%9D%8F%22%5D%0A%20%20ISO%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20HARD%5B%22%E6%8F%90%E9%AB%98%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>堆完整性是分配器不变量。整数溢出下一课常是「算错长度再交给分配器/复制」的上游。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无 unlink 配方。整数溢出漏洞下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UAF 串对象；溢出/双重释放可直接改分配器账本。</li><li>隔离元数据与校验指针是加固。</li><li>仍非内存安全。</li><li>下一课整数溢出。</li><li>出处：Szekeres et al.；Doug Lea allocator notes；对照 CWE-122/415。</li></ul>',8))])}const b=r(p,[["render",E]]);export{k as __pageData,b as default};
